ar=lambda n: str(n).translate(str.maketrans('0123456789','٠١٢٣٤٥٦٧٨٩'))
bar=''.join(f'<div style="flex:{m};background:{c}" title="{n}: {ar(m)} د">{ar(m) if m>1 else ""}</div>' for n,m,c,_ in stages)
steps=''.join(f'<div class="step"><header><h3><span class="dot" style="background:{c}"></span>{n}</h3><span class="min">{ar(m)} د</span></header><p>{d}</p></div>' for n,m,c,d in stages)
